def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    occupied = 0.0
    spheres = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            spheres += o * (4.0 * pi / 3.0) * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * occupied if v is not None and v > 0 else 0.0
    return spheres / volume if volume > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    nearest = [inf for x in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                nearest[i] = min(nearest[i], d / (a + b))
    total = 0.0
    value = 0.0
    for i in range(n):
        if nearest[i] < inf:
            value += occ[i] * nearest[i]
            total += occ[i]
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    coordination = [0.0 for x in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                coordination[i] += occ[j] / (1.0 + (d / (1.2 * (a + b))) ** 12)
    total = sum(occ[i] for i in range(n) if radii[i] is not None and radii[i] > 0)
    return sum(occ[i] * coordination[i] for i in range(n)) / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [x.get('element') for x in sites]
    radii = [(props.get(e) or {}).get('covalent_radius_A') for e in elements]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    counts = {}
    for i in range(n):
        if radii[i] is not None and radii[i] > 0:
            counts[elements[i]] = counts.get(elements[i], 0.0) + occ[i]
    occupied = sum(counts.values())
    if occupied <= 0:
        return 0.0
    total = 0.0
    hetero = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                w = occ[i] * occ[j] / (1.0 + (d / (1.2 * (a + b))) ** 12)
                total += w
                if elements[i] != elements[j]:
                    hetero += w
    expected = 1.0 - sum((v / occupied) ** 2 for v in counts.values())
    return hetero / total - expected if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = []
    targets = []
    occ = []
    for site in sites:
        p = props.get(site.get('element')) or {}
        radii.append(p.get('covalent_radius_A'))
        g = p.get('group')
        target = 0.0
        if p.get('Z') == 1:
            target = 1.0
        elif p.get('row') == 2 and g is not None and 13 <= g <= 17:
            target = float(min(g - 10, 18 - g))
        targets.append(target)
        o = site.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    loads = [0.0 for site in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and targets[i] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= a + b + 1.5:
                loads[i] += occ[j] * min(3.0, exp((a + b - d) / 0.35))
    value = 0.0
    total = 0.0
    for i in range(n):
        if targets[i] > 0 and radii[i] is not None and radii[i] > 0:
            value += occ[i] * ((loads[i] - targets[i]) / targets[i]) ** 2
            total += occ[i]
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    records = []
    inverse = 0.0
    weighted = 0.0
    total = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        p = props.get(element) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if fraction is not None and fraction > 0 and ion is not None and affinity is not None and ion > affinity:
            chi = 0.5 * (ion + affinity)
            hardness = max(0.5, ion - affinity)
            records.append((fraction, chi, hardness))
            inverse += fraction / hardness
            weighted += fraction * chi / hardness
            total += fraction
    if inverse <= 0 or total <= 0:
        return 0.0
    chemical_potential = weighted / inverse
    return 0.5 * sum(f * (chi - chemical_potential) ** 2 / hardness for f, chi, hardness in records) / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    if any(row is None or len(row) != 3 for row in matrix):
        return 0.0
    coords = [site.get('frac_coords') for site in sites]
    occ = [max(0.0, site.get('occupancy') if site.get('occupancy') is not None else 1.0) for site in sites]
    contacts = [[] for site in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        image = edge.get('image')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            if coords[i] is not None and coords[j] is not None and len(coords[i]) == 3 and len(coords[j]) == 3 and image is not None and len(image) == 3:
                contacts[i].append((d, j, image[0], image[1], image[2]))
    value = 0.0
    total = 0.0
    for i in range(n):
        if len(contacts[i]) < 4:
            continue
        vectors = []
        for record in sorted(contacts[i])[:4]:
            j = record[1]
            delta = [coords[j][k] + record[k + 2] - coords[i][k] for k in range(3)]
            vector = [sum(delta[k] * matrix[k][a] for k in range(3)) for a in range(3)]
            norm = sqrt(sum(x * x for x in vector))
            if norm > 0:
                vectors.append([x / norm for x in vector])
        if len(vectors) != 4:
            continue
        penalty = 0.0
        for a in range(4):
            for b in range(a + 1, 4):
                cosine = max(-1.0, min(1.0, sum(vectors[a][k] * vectors[b][k] for k in range(3))))
                penalty += (cosine + 1.0 / 3.0) ** 2
        value += occ[i] * (1.0 - 3.0 * penalty / 8.0)
        total += occ[i]
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    first = [inf for site in sites]
    second = [inf for site in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            if d < first[i]:
                second[i] = first[i]
                first[i] = d
            elif d < second[i]:
                second[i] = d
    value = 0.0
    total = 0.0
    for i in range(n):
        if first[i] < inf:
            next_distance = second[i] if second[i] < inf else max(6.0, first[i])
            value += occ[i] * log(max(1.0, next_distance / first[i]))
            total += occ[i]
    return value / total if total > 0 else 0.0
